export function handleAuthStateChange({ email, userId, customerId, loggedInNew, }) {
    const storageData = {};
    const keysToRemove = [];
    // Handle email
    if (email === null) {
        keysToRemove.push('email');
    }
    else if (email) {
        storageData.email = email;
    }
    // Handle userId
    if (userId === null) {
        keysToRemove.push('userId');
    }
    else if (userId) {
        storageData.userId = userId;
    }
    // Handle customerId
    if (customerId === null) {
        keysToRemove.push('customerId');
    }
    else if (customerId) {
        storageData.customerId = customerId;
    }
    // Handle loggedInNew
    if (loggedInNew === null) {
        keysToRemove.push('loggedInNew');
    }
    else if (loggedInNew !== undefined) {
        storageData.loggedInNew = loggedInNew;
    }
    // Set new/updated data
    if (Object.keys(storageData).length > 0) {
        chrome.storage.local.set(storageData, () => {
        });
    }
    // Remove null keys
    if (keysToRemove.length > 0) {
        chrome.storage.local.remove(keysToRemove, () => {
        });
    }
}
